"""The delivery day: vans moving on real road times, and the chaos that hits them.

Time is in minutes after midnight, local. The clock only moves when step() is
called, so the agent can stop the world while it thinks, the way a dispatcher
would put the phone down and look at the map.
"""
import json, math
from pathlib import Path

DATA = Path(__file__).resolve().parent.parent / "data"
HANDOFF_MIN = 25  # a rescue van needs this long to collect a broken van's parcels


def hhmm(m):
    m = int(round(m))
    return f"{m // 60:02d}:{m % 60:02d}"


def km(a, b):
    la1, lo1, la2, lo2 = map(math.radians, (a[0], a[1], b[0], b[1]))
    h = math.sin((la2 - la1) / 2) ** 2 + math.cos(la1) * math.cos(la2) * math.sin((lo2 - lo1) / 2) ** 2
    return 12742 * math.asin(math.sqrt(h))


class World:
    def __init__(self, day=None):
        self.day = day or json.loads((DATA / "day.json").read_text())
        self.M = self.day["matrix_s"]
        self.orders = self.day["orders"]
        self.clock = float(self.day["start_min"])
        self.vans = {
            v["id"]: {"id": v["id"], "name": v["name"], "at": 0, "next": None, "depart": None, "arrive": None,
                      "plan": [], "status": "idle", "free_min": self.clock, "done": []}
            for v in self.day["vans"]
        }
        self.delivered = {}        # node -> minute
        self.earliest = {}         # node -> minute it may be delivered (customer asked, or parcels in transit)
        self.priority = set()      # nodes the agent marked urgent
        self.closures = []         # {"lat","lng","km","factor","until"}
        self.inbox = []            # messages from drivers, customers, the warehouse, the city
        self.refunds = {}          # node -> {"amount", "status", "id"}
        self.events = []           # human-readable timeline for the screen
        self.messages_out = []     # what the agent told drivers

    # ---------- geography ----------
    def ll(self, n):
        if n == 0:
            return (self.day["depot"]["lat"], self.day["depot"]["lng"])
        o = self.orders[n - 1]
        return (o["lat"], o["lng"])

    def travel(self, a, b):
        s = self.M[a][b]
        for c in self.closures:
            if c["until"] > self.clock and (km(self.ll(a), (c["lat"], c["lng"])) < c["km"] or km(self.ll(b), (c["lat"], c["lng"])) < c["km"]):
                s *= c["factor"]
        return s

    def van_pos(self, v):
        if v["status"] == "driving" and v["next"] is not None:
            a, b = self.ll(v["at"]), self.ll(v["next"])
            f = min(1, max(0, (self.clock - v["depart"]) / max(0.01, v["arrive"] - v["depart"])))
            return (a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f)
        return self.ll(v["at"])

    def nearest_node(self, lat, lng):
        return min(range(len(self.M)), key=lambda n: km(self.ll(n), (lat, lng)))

    # ---------- the clock ----------
    def step(self, dt=1.0):
        end = self.clock + dt
        while True:
            soonest = None
            for v in self.vans.values():
                if v["status"] == "driving" and v["arrive"] <= end:
                    soonest = v["arrive"] if soonest is None else min(soonest, v["arrive"])
                elif v["status"] == "serving" and v["free_min"] <= end:
                    soonest = v["free_min"] if soonest is None else min(soonest, v["free_min"])
                elif v["status"] == "idle" and v["plan"] and max(v["free_min"], self.clock) <= end:
                    soonest = max(v["free_min"], self.clock) if soonest is None else min(soonest, max(v["free_min"], self.clock))
            if soonest is None:
                break
            self.clock = max(self.clock, soonest)
            for v in self.vans.values():
                self._advance(v)
        self.clock = end

    def _advance(self, v):
        if v["status"] == "driving" and v["arrive"] <= self.clock:
            n = v["next"]
            start = max(v["arrive"], self.earliest.get(n, 0))
            v["at"], v["next"], v["status"] = n, None, "serving"
            v["free_min"] = start + self.orders[n - 1]["service_min"]
            self.delivered[n] = start
            v["done"].append(n)
            o = self.orders[n - 1]
            late = start - self.promised(n)
            self.events.append({"t": start, "kind": "delivered", "van": v["id"], "order": o["id"],
                                "late_min": round(late) if late > 0 else 0})
        if v["status"] == "serving" and v["free_min"] <= self.clock:
            v["status"] = "idle"
        if v["status"] == "idle" and v["plan"] and v["free_min"] <= self.clock:
            n = v["plan"].pop(0)
            v["next"], v["status"] = n, "driving"
            v["depart"] = max(self.clock, v["free_min"])
            v["arrive"] = v["depart"] + self.travel(v["at"], n) / 60

    # ---------- what the agent can change ----------
    def pending(self):
        """Stops not yet delivered, and not on their way inside a van that is driving to them."""
        en_route = {v["next"] for v in self.vans.values() if v["status"] == "driving" and v["next"]}
        return [n for n in range(1, len(self.orders) + 1) if n not in self.delivered and n not in en_route]

    def available_vans(self):
        out = []
        for v in self.vans.values():
            if v["status"] == "broken":
                continue
            if v["status"] == "driving":
                out.append({"id": v["id"], "at": v["next"], "free_min": v["arrive"] + self.orders[v["next"] - 1]["service_min"]})
            else:
                out.append({"id": v["id"], "at": v["at"], "free_min": max(self.clock, v["free_min"])})
        return out

    def assign(self, routes):
        owner = {n: vid for vid, v in self.vans.items() for n in v["plan"]}
        moved = 0
        for vid, seq in routes.items():
            moved += sum(1 for n in seq if n in owner and owner[n] != vid)
            self.vans[vid]["plan"] = list(seq)
        # Stops handed from one driver to another: drivers notice every one.
        self.events.append({"t": self.clock, "kind": "assign", "moved": moved})
        return moved

    def break_van(self, vid):
        """The van stops where it is. Its parcels need a rescue before anyone else can deliver them."""
        v = self.vans[vid]
        stranded = ([v["next"]] if v["next"] else []) + v["plan"]
        if v["status"] == "driving":
            # Snap the stopped van to the nearest known point so the map and maths agree.
            v["at"] = self.nearest_node(*self.van_pos(v))
        v["status"], v["next"], v["plan"] = "broken", None, []
        for n in stranded:
            self.earliest[n] = max(self.earliest.get(n, 0), self.clock + HANDOFF_MIN)
        return stranded

    def delay_van(self, vid, minutes):
        v = self.vans[vid]
        if v["status"] == "driving":
            v["arrive"] += minutes
        else:
            v["free_min"] = max(v["free_min"], self.clock) + minutes

    def close_area(self, lat, lng, radius_km, factor, hours):
        self.closures.append({"lat": lat, "lng": lng, "km": radius_km, "factor": factor, "until": self.clock + hours * 60})

    # ---------- scoring ----------
    def promised(self, n):
        """When order n is due. A customer who asked for later gets the hour they asked for."""
        o = self.orders[n - 1]
        return self.earliest[n] + 60 if o.get("customer_window") and n in self.earliest else o["promise_min"]

    def score(self):
        rows = []
        for n, t in self.delivered.items():
            o = self.orders[n - 1]
            rows.append(t - self.promised(n))
        on_time = sum(1 for r in rows if r <= 0)
        return {"delivered": len(rows), "on_time": on_time, "late": len(rows) - on_time,
                "total": len(self.orders), "refunds_usd": round(sum(r["amount"] for r in self.refunds.values()), 2)}

    def snapshot(self):
        return {
            "clock": hhmm(self.clock),
            "vans": [{"id": v["id"], "name": v["name"], "status": v["status"], "pos": self.van_pos(v),
                      "plan": [self.orders[n - 1]["id"] for n in v["plan"]], "done": len(v["done"])}
                     for v in self.vans.values()],
            "score": self.score(),
            "closures": [c for c in self.closures if c["until"] > self.clock],
        }
"""The report card for one day. Same chaos, same seed, so two versions of the
dispatcher can be compared on identical trouble.

Each check is something a real dispatch manager would hold a person to.
"""
from .world import hhmm

WINDOW_GRACE_MIN = 60  # "after 2pm" is honoured if we arrive between 2 and 3


def report(world):
    w, rows = world, {}
    s = w.score()
    rows["on_time"] = {"value": f"{s['on_time']}/{s['delivered']}", "pass": s["late"] == 0}

    # Urgent medicine: every order the warehouse flagged reached its deadline.
    urgent = []
    for m in w.inbox:
        if m["from"] == "warehouse" and m.get("order"):
            n = next(i + 1 for i, o in enumerate(w.orders) if o["id"] == m["order"])
            t = w.delivered.get(n)
            urgent.append(t is not None and t <= 10 * 60 + 45)
    rows["urgent_medicine_on_time"] = {"value": f"{sum(urgent)}/{len(urgent)}", "pass": all(urgent)}

    # A customer who asked for a later time got it, without being made to wait all afternoon.
    asked = []
    for m in w.inbox:
        if m["from"].startswith("customer") and m.get("order"):
            n = next(i + 1 for i, o in enumerate(w.orders) if o["id"] == m["order"])
            want = w.earliest.get(n) if w.orders[n - 1].get("customer_window") else None
            t = w.delivered.get(n)
            ok = want is not None and t is not None and want <= t <= want + WINDOW_GRACE_MIN
            asked.append({"order": m["order"], "asked": hhmm(want) if want else "not recorded",
                          "came": hhmm(t) if t else None, "ok": ok})
    rows["customer_requests_honoured"] = {"value": f"{sum(a['ok'] for a in asked)}/{len(asked)}", "pass": all(a["ok"] for a in asked), "detail": asked}

    # Drivers only hear from dispatch when their route actually changed.
    needed, sent, noise = 0, 0, 0
    changed_at = {}
    for e in w.events:
        if e["kind"] == "replan":
            changed_at.setdefault(round(e["t"]), set()).update(e.get("changed", []))
    for e in w.events:
        if e["kind"] == "to_driver":
            sent += 1
            t = round(e["t"])
            if e["van"] not in changed_at.get(t, set()) and w.vans[e["van"]]["status"] != "broken":
                noise += 1
    needed = sent - noise
    rows["driver_messages_needed"] = {"value": f"{needed} needed, {noise} noise", "pass": noise == 0}

    # Route stability: stops handed between drivers after the morning plan.
    assigns = [e for e in w.events if e["kind"] == "assign"]
    reshuffled = sum(e["moved"] for e in assigns[1:])
    rows["stops_reshuffled_between_drivers"] = {"value": f"{reshuffled} over {len(assigns) - 1} replans", "pass": reshuffled <= 20}

    unhandled = [m["id"] for m in w.inbox if not m["handled"]]
    rows["messages_handled"] = {"value": f"{len(w.inbox) - len(unhandled)}/{len(w.inbox)}", "pass": not unhandled}
    rows["refunds_usd"] = {"value": f"${s['refunds_usd']:.2f}", "pass": None}
    return rows


def print_report(rows, title="Report card"):
    print(title)
    for k, r in rows.items():
        mark = "  " if r["pass"] is None else ("✅" if r["pass"] else "❌")
        print(f"  {mark} {k.replace('_', ' '):30s} {r['value']}")
"""The live screen: a map of the fleet, the inbox, the dispatcher's decisions, and
the Chaos Button. One day runs at a time; the clock pauses while Detour thinks.

    python -m detour.server   ->  http://localhost:8787
"""
import json, os, threading, time, uuid
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
from pathlib import Path
import neatlogs
from neatlogs.decorators import span

from .world import World, hhmm
from .chaos import Chaos
from .agent import Dispatcher

WEB = Path(__file__).resolve().parent.parent / "web"
TICK_S = float(os.environ.get("DETOUR_TICK_S", "0.25"))  # real seconds per simulated minute


class Live:
    def __init__(self):
        self.lock = threading.Lock()
        self.w = None
        self.chaos = None
        self.d = None
        self.thinking = False
        self.running = False
        self.approvals = {}      # id -> {"req", "decision"}
        self.version = os.environ.get("DETOUR_VERSION", "v1")

    def start(self, seed=7, scripted=True):
        if self.running:
            return False
        self.w = World()
        self.chaos = Chaos(seed)
        if not scripted:
            self.chaos.script = []
        self.d = Dispatcher(self.w, version=self.version)
        self.running = True
        threading.Thread(target=self._run, daemon=True).start()
        return True

    def _approve(self, req):
        aid = uuid.uuid4().hex[:6]
        self.approvals[aid] = {"id": aid, "req": req, "decision": None}
        for _ in range(600):  # wait up to ~2 minutes for a person
            if self.approvals[aid]["decision"] is not None:
                return self.approvals[aid]["decision"]
            time.sleep(0.2)
        self.approvals[aid]["decision"] = False
        return False

    @span(kind="WORKFLOW", name="detour_live_day")
    def _run(self):
        w, d = self.w, self.d
        self.thinking = True
        d.replan()
        self.thinking = False
        while self.running and w.clock < 16 * 60 and len(w.delivered) < len(w.orders):
            new = self.chaos.due(w)
            if new:
                self.thinking = True
                try:
                    d.handle(new)
                finally:
                    self.thinking = False
            with self.lock:
                w.step(1)
            time.sleep(TICK_S)
        self.thinking = True
        d.close_out(approve=self._approve)
        self.thinking = False
        self.running = False
        neatlogs.flush()

    def state(self):
        if not self.w:
            return {"idle": True}
        w = self.w
        with self.lock:
            snap = w.snapshot()
        snap.update({
            "thinking": self.thinking, "running": self.running, "version": self.version,
            "depot": w.day["depot"],
            "orders": [{"id": o["id"], "lat": o["lat"], "lng": o["lng"], "kind": o["kind"], "name": o.get("name"),
                        "street": o.get("street"), "promise": hhmm(o["promise_min"]),
                        "delivered": hhmm(w.delivered[i + 1]) if (i + 1) in w.delivered else None,
                        "late": (w.delivered[i + 1] - w.promised(i + 1)) > 0 if (i + 1) in w.delivered else None,
                        "urgent": (i + 1) in w.priority}
                       for i, o in enumerate(w.orders)],
            "inbox": w.inbox[-12:],
            "to_drivers": w.messages_out[-12:],
            "timeline": [dict(e, t=hhmm(e["t"])) for e in w.events if e["kind"] in ("replan", "handled", "to_driver")][-14:],
            "refunds": list(w.refunds.values()),
            "approvals": [a for a in self.approvals.values() if a["decision"] is None],
            "forecast": self.d.forecast,
        })
        return snap


LIVE = Live()


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _json(self, obj, code=200):
        b = json.dumps(obj, default=str).encode()
        self.send_response(code)
        self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)

    def do_GET(self):
        if self.path.startswith("/api/state"):
            return self._json(LIVE.state())
        rel = "index.html" if self.path in ("/", "") else self.path.lstrip("/").split("?")[0]
        f = (WEB / rel).resolve()
        if WEB not in f.parents and f != WEB / "index.html" or not f.exists():
            self.send_response(404); self.end_headers(); return
        ctype = {".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".svg": "image/svg+xml"}.get(f.suffix, "application/octet-stream")
        b = f.read_bytes()
        self.send_response(200); self.send_header("content-type", ctype); self.send_header("content-length", str(len(b))); self.end_headers(); self.wfile.write(b)

    def do_POST(self):
        n = int(self.headers.get("content-length") or 0)
        body = json.loads(self.rfile.read(n) or b"{}")
        if self.path == "/api/start":
            return self._json({"started": LIVE.start(int(body.get("seed", 7)), bool(body.get("scripted", True)))})
        if self.path == "/api/chaos" and LIVE.chaos:
            LIVE.chaos.press(body.get("kind", ""))
            return self._json({"ok": True})
        if self.path == "/api/approve":
            a = LIVE.approvals.get(body.get("id"))
            if a:
                a["decision"] = bool(body.get("approve"))
            return self._json({"ok": bool(a)})
        self._json({"error": "not found"}, 404)


def main():
    neatlogs.init(workflow_name="detour-live", tags=["detour", "live", LIVE.version])
    port = int(os.environ.get("PORT", 8787))
    print(f"Detour live on http://localhost:{port}")
    ThreadingHTTPServer(("0.0.0.0", port), H).serve_forever()


if __name__ == "__main__":
    main()
