the manager's 👎 rules.

Talks to the neatlogs MCP server over HTTP (the same one Claude Code uses), with the
token from NEATLOGS_MCP_TOKEN or the git-ignored .mcp.json.

    python -m detour.neat sync      # make sure every rule in detour/rules.py has its detection
    python -m detour.neat list      # the rules neatlogs is watching
"""
import json, os, re, sys
from pathlib import Path
import httpx

from .rules import RULES

ROOT = Path(__file__).resolve().parent.parent
GROUP = "Dispatcher rules"
SPANS = ["dispatcher_decision", "manager_feedback"]
MANAGER = "Manager rule"   # description prefix that marks a rule added from the 👎 button
CACHE = ROOT / "runs" / "manager-rules.json"
URL = os.environ.get("NEATLOGS_MCP_URL", "https://ingest.neatlogs.com/mcp")
TRACE_URL = os.environ.get("NEATLOGS_TRACE_URL", "https://app.neatlogs.com/project/{project}/traces/{trace}")


def trace_url(trace_id, span_id=None):
    if not trace_id:
        return None
    return TRACE_URL.format(project=os.environ.get("NEATLOGS_PROJECT_ID", ""), trace=trace_id, span=span_id or "")


def _token():
    if os.environ.get("NEATLOGS_MCP_TOKEN"):
        return os.environ["NEATLOGS_MCP_TOKEN"]
    cfg = json.loads((ROOT / ".mcp.json").read_text())["mcpServers"]["neatlogs"]
    return cfg["headers"]["Authorization"].split(" ", 1)[1]


class MCP:
    def __init__(self):
        self.h = {"Authorization": f"Bearer {_token()}", "Accept": "application/json, text/event-stream",
                  "Content-Type": "application/json"}
        self.c = httpx.Client(timeout=60)
        self.n = 0
        r = self._post({"method": "initialize", "params": {"protocolVersion": "2025-03-26", "capabilities": {},
                                                           "clientInfo": {"name": "detour", "version": "1"}}})
        if r.headers.get("mcp-session-id"):
            self.h["mcp-session-id"] = r.headers["mcp-session-id"]
        self.c.post(URL, headers=self.h, json={"jsonrpc": "2.0", "method": "notifications/initialized"})

    def _post(self, body):
        self.n += 1
        r = self.c.post(URL, headers=self.h, json={"jsonrpc": "2.0", "id": self.n, **body})
        r.raise_for_status()
        return r

    def call(self, tool, **args):
        r = self._post({"method": "tools/call", "params": {"name": tool, "arguments": args}})
        text = r.text
        if "text/event-stream" in r.headers.get("content-type", ""):
            text = "\n".join(l[5:] for l in text.splitlines() if l.startswith("data:"))
        res = json.loads(text)["result"]
        out = res["content"][0]["text"]
        if res.get("isError"):
            raise RuntimeError(out[:300])
        try:
            return json.loads(out)
        except json.JSONDecodeError:
            return out


def pattern(rule):
    return "RULE BROKEN: " + re.escape(rule)


def group_id(m):
    for g in m.call("list_detection_groups")["groups"]:
        if g["name"] == GROUP:
            return g["id"]
    return m.call("create_detection_group", name=GROUP)["id"]


def detections(m=None):
    m = m or MCP()
    return [d for d in m.call("list_detections", group_id=group_id(m))["detections"]]


def ensure(rule, description, m=None):
    """One neatlogs detection per rule: it flags any decision record that says the rule was broken."""
    m = m or MCP()
    for d in detections(m):
        if d["display_name"] == rule:
            return {"id": d["id"], "created": False}
    config = {"output_pattern": pattern(rule), "case_sensitive": True}
    run_on = {"frequency": "span_name", "span_names": SPANS}
    preview = m.call("preview_detection", type="regex", config=config, run_on=run_on, timeframe_days=14, limit=5)
    made = m.call("create_detection", display_name=rule, description=description, group_id=group_id(m),
