def manager_rules():
    """The manager's rules, from neatlogs (the source of truth), with a local copy if neatlogs is unreachable."""
    try:
        out = [d["display_name"] for d in detections() if (d.get("description") or "").startswith(MANAGER)]
        CACHE.parent.mkdir(exist_ok=True)
        CACHE.write_text(json.dumps(out, indent=1))
        return out
    except Exception:
        return json.loads(CACHE.read_text()) if CACHE.exists() else []


def sync():
    m = MCP()
    for key, rule in RULES.items():
        r = ensure(rule, f"Business rule '{key}': checked by detour/rules.py on every dispatcher decision; "
                         f"flags a dispatcher_decision span that says this rule was broken.", m)
        print(("created " if r["created"] else "exists  ") + rule, r)


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else "list"
    if cmd == "sync":
        sync()
    else:
        for d in detections():
            print(f"{d['display_name']}  [{d['type']}, active={d['is_active']}]  {d.get('description', '')[:80]}")

